package com.dpworld.fms.mapimport;
import com.dpworld.fms.domain.GeoPoint;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;import crosby.binary.osmosis.OsmosisReader;import java.io.*;import java.nio.file.*;import java.util.*;import org.openstreetmap.osmosis.core.container.v0_6.*;import org.openstreetmap.osmosis.core.domain.v0_6.*;import org.openstreetmap.osmosis.core.task.v0_6.Sink;
public final class OsmPbfGraphImporter {
 private final Set<String>acceptedHighways;private final double defaultSpeedKph;
 public OsmPbfGraphImporter(Set<String>acceptedHighways,double defaultSpeedKph){this.acceptedHighways=Set.copyOf(acceptedHighways);if(defaultSpeedKph<=0)throw new IllegalArgumentException("default speed must be positive");this.defaultSpeedKph=defaultSpeedKph;}
 public ImportedRoutingGraph read(Path pbf,Path overrideFile)throws IOException{if(!Files.isRegularFile(pbf))throw new IllegalArgumentException("PBF file does not exist: "+pbf);TerminalOverrides overrides=overrideFile==null?TerminalOverrides.empty():new ObjectMapper(new YAMLFactory()).readValue(overrideFile.toFile(),TerminalOverrides.class);Collector collector=new Collector();try(InputStream input=Files.newInputStream(pbf)){OsmosisReader reader=new OsmosisReader(input);reader.setSink(collector);reader.run();}return build(collector.nodes,collector.ways,overrides);}
 ImportedRoutingGraph build(Map<Long,RawNode>rawNodes,List<RawWay>ways,TerminalOverrides overrides){List<String>errors=new ArrayList<>(),warnings=new ArrayList<>();Map<String,ImportedRoutingGraph.Node>nodes=new LinkedHashMap<>();List<ImportedRoutingGraph.Segment>segments=new ArrayList<>();Set<String>codes=new HashSet<>();for(RawWay way:ways){String highway=way.tags.get("highway");if(!acceptedHighways.contains(highway)||"no".equals(way.tags.get("access"))||"private".equals(way.tags.get("access"))||overrides.disabledRoads().contains(way.id))continue;List<Long>refs=way.nodeIds;String direction=overrides.directionOverrides().getOrDefault(way.id,way.tags.getOrDefault("oneway","no"));boolean reverse="-1".equals(direction),oneway=reverse||Set.of("yes","1","true").contains(direction);double speed=overrides.speedOverrides().getOrDefault(way.id,parseSpeed(way.tags.get("maxspeed"),warnings,way.id));if(speed<=0){errors.add("Way "+way.id+" has non-positive speed override");continue;}for(int i=0;i<refs.size()-1;i++){RawNode left=rawNodes.get(refs.get(i)),right=rawNodes.get(refs.get(i+1));if(left==null||right==null){errors.add("Way "+way.id+" references missing node at sequence "+i);continue;}if(!valid(left)||!valid(right)){errors.add("Way "+way.id+" contains invalid coordinates at sequence "+i);continue;}ImportedRoutingGraph.Node a=node(nodes,left),b=node(nodes,right);double distance=new GeoPoint(a.latitude(),a.longitude()).distanceMetres(new GeoPoint(b.latitude(),b.longitude()));if(distance<=.01){errors.add("Way "+way.id+" has zero-length segment at sequence "+i);continue;}List<String>types=overrides.vehicleRestrictions().getOrDefault(way.id,List.of());if(reverse)add(segments,way,i,b,a,distance,speed,"REVERSE",types,codes,errors);else{add(segments,way,i,a,b,distance,speed,"FORWARD",types,codes,errors);if(!oneway)add(segments,way,i,b,a,distance,speed,"REVERSE",types,codes,errors);}}}for(TerminalOverrides.PrivateNode n:overrides.surveyedPrivateNodes()){if(n.latitude()<-90||n.latitude()>90||n.longitude()<-180||n.longitude()>180){errors.add("Private node "+n.code()+" has invalid coordinates");continue;}if(nodes.putIfAbsent(n.code(),new ImportedRoutingGraph.Node(uuid("node:"+n.code()),n.code(),null,n.latitude(),n.longitude(),"SURVEYED",Map.of()))!=null)errors.add("Duplicate node "+n.code());}for(TerminalOverrides.PrivateSegment s:overrides.surveyedPrivateSegments()){var a=nodes.get(s.from());var b=nodes.get(s.to());if(a==null||b==null){errors.add("Private segment "+s.code()+" references missing node");continue;}double d=new GeoPoint(a.latitude(),a.longitude()).distanceMetres(new GeoPoint(b.latitude(),b.longitude()));if(d<=.01){errors.add("Private segment "+s.code()+" has zero length");continue;}if(s.speedKph()<=0){errors.add("Private segment "+s.code()+" has non-positive speed");continue;}RawWay way=new RawWay(-1,List.of(),Map.of("source","terminal-override","code",s.code()));add(segments,way,0,a,b,d,s.speedKph(),"FORWARD",s.allowedAssetTypes()==null?List.of():s.allowedAssetTypes(),codes,errors);if(!s.oneWay())add(segments,way,1,b,a,d,s.speedKph(),"REVERSE",s.allowedAssetTypes()==null?List.of():s.allowedAssetTypes(),codes,errors);}Map<String,String>resources=new LinkedHashMap<>();mergeResources(resources,overrides.parkingNodes(),errors);mergeResources(resources,overrides.chargingNodes(),errors);mergeResources(resources,overrides.fuelingNodes(),errors);resources.forEach((resource,node)->{if(!nodes.containsKey(node))errors.add("Operational resource "+resource+" references missing node "+node);});int components=components(nodes.keySet(),segments);if(components>1)warnings.add("Graph has "+components+" disconnected components");Set<String>reachable=reachable(nodes.keySet().stream().findFirst().orElse(null),segments);resources.forEach((resource,node)->{if(!reachable.contains(node))errors.add("Operational resource "+resource+" is unreachable at node "+node);});return new ImportedRoutingGraph(List.copyOf(nodes.values()),List.copyOf(segments),new ImportedRoutingGraph.ImportReport(errors.isEmpty(),nodes.size(),segments.size(),components,List.copyOf(errors),List.copyOf(warnings),Map.copyOf(resources)));}
 private void mergeResources(Map<String,String>resources,Map<String,String>additional,List<String>errors){additional.forEach((code,node)->{if(resources.putIfAbsent(code,node)!=null)errors.add("Duplicate operational resource "+code);});}
 private boolean valid(RawNode node){return node.latitude>=-90&&node.latitude<=90&&node.longitude>=-180&&node.longitude<=180;}
 private ImportedRoutingGraph.Node node(Map<String,ImportedRoutingGraph.Node>nodes,RawNode raw){String code="OSM-N-"+raw.id;return nodes.computeIfAbsent(code,k->new ImportedRoutingGraph.Node(uuid("node:"+raw.id),code,raw.id,raw.latitude,raw.longitude,"OSM",raw.tags));}
 private void add(List<ImportedRoutingGraph.Segment>out,RawWay way,int sequence,ImportedRoutingGraph.Node from,ImportedRoutingGraph.Node to,double distance,double speed,String direction,List<String>types,Set<String>codes,List<String>errors){String code=(way.id<0?way.tags.get("code"):"OSM-W-"+way.id)+"-"+sequence+"-"+direction;if(!codes.add(code)){errors.add("Duplicate segment "+code);return;}String geometry="{\"type\":\"LineString\",\"coordinates\":[["+from.longitude()+","+from.latitude()+"],["+to.longitude()+","+to.latitude()+"]]}";out.add(new ImportedRoutingGraph.Segment(uuid("segment:"+code),code,way.id<0?null:way.id,sequence,from.code(),to.code(),distance,speed,direction,false,way.tags,List.copyOf(types),geometry));}
 private double parseSpeed(String value,List<String>warnings,long way){if(value==null||value.isBlank())return defaultSpeedKph;try{String normalized=value.toLowerCase(Locale.ROOT).replace("km/h","").trim();double speed=Double.parseDouble(normalized.replaceAll("[^0-9.]",""));if(value.toLowerCase(Locale.ROOT).contains("mph"))speed*=1.609344;if(speed<=0)throw new NumberFormatException();return speed;}catch(NumberFormatException e){warnings.add("Way "+way+" has invalid maxspeed; using configured default");return defaultSpeedKph;}}
 private int components(Set<String>nodes,List<ImportedRoutingGraph.Segment>segments){Set<String>seen=new HashSet<>();int count=0;for(String node:nodes)if(seen.add(node)){count++;Deque<String>queue=new ArrayDeque<>();queue.add(node);while(!queue.isEmpty()){String at=queue.remove();segments.stream().filter(s->s.from().equals(at)||s.to().equals(at)).map(s->s.from().equals(at)?s.to():s.from()).filter(seen::add).forEach(queue::add);}}return count;}
 private Set<String>reachable(String start,List<ImportedRoutingGraph.Segment>segments){Set<String>seen=new HashSet<>();if(start==null)return seen;Deque<String>queue=new ArrayDeque<>();seen.add(start);queue.add(start);while(!queue.isEmpty()){String at=queue.remove();segments.stream().filter(s->s.from().equals(at)).map(ImportedRoutingGraph.Segment::to).filter(seen::add).forEach(queue::add);}return seen;}
 private UUID uuid(String value){return UUID.nameUUIDFromBytes(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 static record RawNode(long id,double latitude,double longitude,Map<String,String>tags){}static record RawWay(long id,List<Long>nodeIds,Map<String,String>tags){}
 private static final class Collector implements Sink{final Map<Long,RawNode>nodes=new HashMap<>();final List<RawWay>ways=new ArrayList<>();public void initialize(Map<String,Object>meta){}public void process(EntityContainer c){Entity e=c.getEntity();if(e instanceof Node n)nodes.put(n.getId(),new RawNode(n.getId(),n.getLatitude(),n.getLongitude(),tags(n.getTags())));else if(e instanceof Way w)ways.add(new RawWay(w.getId(),w.getWayNodes().stream().map(WayNode::getNodeId).toList(),tags(w.getTags())));}public void complete(){}public void close(){}private static Map<String,String>tags(Collection<Tag>tags){Map<String,String>result=new HashMap<>();tags.forEach(t->result.put(t.getKey(),t.getValue()));return Map.copyOf(result);}}
}
